  'plans.faqWhatIsPlus': 'Какво е Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Това е премиум планът на Chatyy, който защитава всичките ви разговори, снимки и видеа. С Chatyy One, дори ако изтриете нещо по погрешка, можете да го възстановите до 30 дни. Освен това, получавате 200GB пространство за съхранение, One AI като личен асистент и можете да изпращате файлове до 100MB.',
  'plans.faqCancelAnswer': 'Вашият план остава активен до края на платения период. След това, ще се върнете към безплатния план. Вашите снимки и видеа, които надвишават 15GB, ще бъдат запазени за още 30 дни, за да можете да ги изтеглите.',
